// INPUT VALIDATION & NORMALIZATION
const body = $input.first().json.body || $input.first().json;

const handle = (body.handle || '').toString().trim().replace(/^@/, '');
const platform = (body.platform || 'instagram').toString().toLowerCase();
const claimedNiche = (body.claimed_niche || 'lifestyle').toString().trim();
const claimedAudience = (body.claimed_audience || 'US').toString().trim();
const claimedFollowers = parseInt(body.claimed_followers || 0);

if (!handle) {
  throw new Error('Influencer handle is required.');
}

const validPlatforms = ['instagram', 'tiktok', 'youtube'];
if (!validPlatforms.includes(platform)) {
  throw new Error(`Platform must be one of: ${validPlatforms.join(', ')}`);
}

return [{
  json: {
    handle,
    platform,
    claimedNiche,
    claimedAudience,
    claimedFollowers,
    auditId: `audit_${Date.now()}`,
    auditStartedAt: new Date().toISOString()
  }
}];

// BRANCH 1: FOLLOWER SPIKE DETECTOR
// Analyzes follower growth data for abnormal spikes

const input = $input.first().json;
const platform = $('Validate & Normalize Input').item.json.platform;
const claimedFollowers = $('Validate & Normalize Input').item.json.claimedFollowers || 0;

// Simulate parsed follower history from scrape result
// In real run, parse from Apify response
let followerHistory = input.followerHistory || input.followersHistory || [];

// If no history returned, build a stub from available data
if (!followerHistory || followerHistory.length === 0) {
  const currentFollowers = input.followersCount || input.stats?.followers || input.followerCount || claimedFollowers || 10000;
  followerHistory = [
    { date: '30_days_ago', count: Math.floor(currentFollowers * 0.82) },
    { date: '21_days_ago', count: Math.floor(currentFollowers * 0.85) },
    { date: '14_days_ago', count: Math.floor(currentFollowers * 0.88) },
    { date: '7_days_ago', count: Math.floor(currentFollowers * 0.94) },
    { date: 'today', count: currentFollowers }
  ];
}

// Detect spikes: flag if any single-period growth > 15% of total followers
const spikes = [];
let maxSpikePercent = 0;
for (let i = 1; i < followerHistory.length; i++) {
  const prev = followerHistory[i - 1].count;
  const curr = followerHistory[i].count;
  const diff = curr - prev;
  const pct = prev > 0 ? (diff / prev) * 100 : 0;
  if (pct > 15) {
    spikes.push({
      period: followerHistory[i].date,
      gained: diff,
      growthPercent: pct.toFixed(1)
    });
    if (pct > maxSpikePercent) maxSpikePercent = pct;
  }
}

// Score: 0 (clean) to 100 (highly suspicious)
let spikeScore = 0;
if (maxSpikePercent > 50) spikeScore = 90;
else if (maxSpikePercent > 30) spikeScore = 70;
else if (maxSpikePercent > 15) spikeScore = 45;
else spikeScore = 10;

return [{
  json: {
    branch: 'follower_spike',
    spikeScore,
    spikesDetected: spikes.length,
    spikes,
    maxSinglePeriodGrowthPercent: maxSpikePercent.toFixed(1),
    verdict: spikeScore >= 70 ? 'HIGH_RISK' : spikeScore >= 45 ? 'MEDIUM_RISK' : 'LOW_RISK'
  }
}];

// BRANCH 2: ENGAGEMENT RATE ANALYZER
// Computes engagement rate and compares vs healthy benchmarks

const input = $input.first().json;
const claimedFollowers = $('Validate & Normalize Input').item.json.claimedFollowers || 0;
const platform = $('Validate & Normalize Input').item.json.platform;

const posts = input.posts || input.latestPosts || input.items || [];
const followerCount = input.followersCount || input.stats?.followers || claimedFollowers || 10000;

// Healthy engagement benchmarks per tier
const benchmarks = {
  micro:  { min: 3.0,  max: 8.0  },
  mid:    { min: 1.5,  max: 3.0  },
  macro:  { min: 0.5,  max: 1.5  },
  mega:   { min: 0.2,  max: 0.8  }
};

let tier = 'micro';
if (followerCount >= 1000000) tier = 'mega';
else if (followerCount >= 500000) tier = 'macro';
else if (followerCount >= 100000) tier = 'mid';
else tier = 'micro';

// Calculate average engagement
let totalEngagement = 0;
let postCount = Math.min(posts.length, 30);

if (postCount > 0) {
  for (let i = 0; i < postCount; i++) {
    const p = posts[i];
    const likes = p.likesCount || p.likes || p.diggCount || 0;
    const comments = p.commentsCount || p.comments || 0;
    const shares = p.sharesCount || p.shares || p.repostsCount || 0;
    totalEngagement += (likes + comments + shares);
  }
} else {
  // Fallback stub
  postCount = 10;
  totalEngagement = followerCount * 0.02 * postCount;
}

const avgEngagement = totalEngagement / postCount;
const engagementRate = followerCount > 0 ? (avgEngagement / followerCount) * 100 : 0;

const bench = benchmarks[tier];
let engagementScore = 0;
let anomalyType = 'NONE';

if (engagementRate < bench.min * 0.4) {
  engagementScore = 75; // Way too low – ghost followers
  anomalyType = 'SUSPICIOUSLY_LOW';
} else if (engagementRate > bench.max * 3) {
  engagementScore = 80; // Way too high – engagement pods
  anomalyType = 'SUSPICIOUSLY_HIGH';
} else if (engagementRate >= bench.min && engagementRate <= bench.max) {
  engagementScore = 5; // Healthy
  anomalyType = 'HEALTHY';
} else {
  engagementScore = 30; // Slightly off
  anomalyType = 'SLIGHTLY_ABNORMAL';
}

return [{
  json: {
    branch: 'engagement_rate',
    followerTier: tier,
    followerCount,
    engagementRate: engagementRate.toFixed(2),
    benchmarkMin: bench.min,
    benchmarkMax: bench.max,
    engagementScore,
    anomalyType,
    verdict: engagementScore >= 70 ? 'HIGH_RISK' : engagementScore >= 40 ? 'MEDIUM_RISK' : 'LOW_RISK'
  }
}];

// BRANCH 3: PRE-FILTER COMMENTS (Rules-based, no API cost)
// Filters out obvious bots before sending to Claude

const input = $input.first().json;
const allPosts = input.posts || input.latestPosts || input.items || [];

// Collect all comments from all posts
let allComments = [];
for (const post of allPosts) {
  const postComments = post.comments || post.latestComments || [];
  allComments = allComments.concat(postComments);
}

// Stub if no comments returned
if (allComments.length === 0) {
  allComments = [
    { text: 'Nice!', ownerUsername: 'user12345' },
    { text: '🔥🔥🔥', ownerUsername: 'follower98765' },
    { text: 'Great post love it so much amazing content', ownerUsername: 'bot_user_1' },
    { text: 'Check my page for free stuff', ownerUsername: 'promo_bot_2023' },
    { text: 'First!', ownerUsername: 'realuser_sarah' },
    { text: 'This is so helpful, I tried this last week and it works', ownerUsername: 'authentic_mark' },
    { text: '❤️❤️❤️', ownerUsername: 'emojispammer111' },
    { text: 'Nice nice nice nice nice', ownerUsername: 'repetitive_bot' }
  ];
}

const totalComments = allComments.length;
let flaggedComments = [];
let cleanComments = [];

// Rule-based bot detection
const botPatterns = [
  /^[\u{1F300}-\u{1FFFF}\s]+$/u,  // Emoji only
  /^(nice|great|amazing|love it|wow|fire|cool|awesome)[!.]*$/i, // Single generic word
  /follow (me|back|4 follow)/i,    // Follow-for-follow
  /check (my|out my) (page|profile|link)/i, // Promo spam
  /free (gift|followers|likes)/i,  // Giveaway spam
];

const duplicateTracker = {};

for (const comment of allComments) {
  const text = (comment.text || comment.content || '').trim();
  const username = comment.ownerUsername || comment.username || '';

  let isBotFlag = false;
  let reason = '';

  // Check 1: Length < 3 words
  if (text.split(' ').filter(w => w.length > 0).length < 3) {
    isBotFlag = true;
    reason = 'TOO_SHORT';
  }

  // Check 2: Regex patterns
  for (const pattern of botPatterns) {
    if (pattern.test(text)) {
      isBotFlag = true;
      reason = 'PATTERN_MATCH';
      break;
    }
  }

  // Check 3: Duplicate comments
  const normalized = text.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (duplicateTracker[normalized]) {
    isBotFlag = true;
    reason = 'DUPLICATE';
  } else {
    duplicateTracker[normalized] = true;
  }

  // Check 4: Username with 5+ trailing digits
  if (/[a-z]{2,}\d{5,}$/i.test(username)) {
    isBotFlag = true;
    reason = reason || 'SUSPICIOUS_USERNAME';
  }

  if (isBotFlag) {
    flaggedComments.push({ text, username, reason });
  } else {
    cleanComments.push({ text, username });
  }
}

const preFilterBotRate = totalComments > 0 ? (flaggedComments.length / totalComments * 100).toFixed(1) : 0;

// Send only borderline clean comments to Claude (max 80 to save tokens)
const commentsForClaude = cleanComments.slice(0, 80);

return [{
  json: {
    branch: 'comment_prefilter',
    totalComments,
    flaggedByRules: flaggedComments.length,
    cleanForClaude: commentsForClaude.length,
    preFilterBotRate: parseFloat(preFilterBotRate),
    flaggedSamples: flaggedComments.slice(0, 5),
    commentsForClaude,
    summary: {
      totalComments,
      obviousBotCount: flaggedComments.length,
      obviousBotPercent: preFilterBotRate
    }
  }
}];

// BRANCH 4: AUDIENCE GEOGRAPHY MISMATCH DETECTOR

const input = $input.first().json;
const claimedAudience = $('Validate & Normalize Input').item.json.claimedAudience || 'US';

const followers = input.followers || input.followersData || [];
const posts = input.posts || input.latestPosts || input.items || [];

// Collect comment languages from posts
let commentTexts = [];
for (const post of posts) {
  const comments = post.comments || post.latestComments || [];
  commentTexts = commentTexts.concat(comments.map(c => c.text || c.content || ''));
}

// Simple language detection heuristics
const languagePatterns = {
  hindi:      /[\u0900-\u097F]/,
  arabic:     /[\u0600-\u06FF]/,
  chinese:    /[\u4E00-\u9FFF]/,
  portuguese: /\b(obrigado|muito|voce|brasil|boa|ótimo)\b/i,
  spanish:    /\b(gracias|hermoso|increíble|bonito|amor)\b/i,
  russian:    /[\u0400-\u04FF]/,
  english:    /\b(the|and|you|this|great|love|amazing)\b/i
};

const langCount = {};
for (const text of commentTexts) {
  for (const [lang, pattern] of Object.entries(languagePatterns)) {
    if (pattern.test(text)) {
      langCount[lang] = (langCount[lang] || 0) + 1;
    }
  }
}

const totalTagged = Object.values(langCount).reduce((a, b) => a + b, 0) || 1;
const langDistribution = {};
for (const [lang, count] of Object.entries(langCount)) {
  langDistribution[lang] = ((count / totalTagged) * 100).toFixed(1) + '%';
}

// Geography mismatch logic
const claimedCountry = claimedAudience.toLowerCase();
const claimedLang = claimedCountry.includes('us') || claimedCountry.includes('uk') || claimedCountry.includes('au') ? 'english' : 'unknown';

let geoMismatchScore = 0;
let mismatchEvidence = [];

const englishPct = langCount['english'] ? (langCount['english'] / totalTagged) : 0;
const nonEnglishPct = 1 - englishPct;

if (claimedLang === 'english' && nonEnglishPct > 0.5) {
  geoMismatchScore = 75;
  mismatchEvidence.push(`Claimed ${claimedAudience} audience but ${(nonEnglishPct * 100).toFixed(0)}% of detected comment language is non-English`);
} else if (claimedLang === 'english' && nonEnglishPct > 0.3) {
  geoMismatchScore = 45;
  mismatchEvidence.push(`Moderate language mismatch for claimed ${claimedAudience} audience`);
} else {
  geoMismatchScore = 10;
}

return [{
  json: {
    branch: 'geo_mismatch',
    claimedAudience,
    detectedLanguageDistribution: langDistribution,
    geoMismatchScore,
    mismatchEvidence,
    verdict: geoMismatchScore >= 70 ? 'HIGH_RISK' : geoMismatchScore >= 40 ? 'MEDIUM_RISK' : 'LOW_RISK'
  }
}];

// BRANCH 5: FOLLOWER QUALITY SPOT CHECK
// Scores a sample of followers for profile authenticity

const input = $input.first().json;

let followers = input.followers || input.followersData || [];

// Stub sample if none returned
if (followers.length === 0) {
  followers = Array.from({ length: 50 }, (_, i) => ({
    username: i % 5 === 0 ? `user${Math.floor(Math.random() * 99999)}` : `realuser_${i}`,
    postsCount: i % 4 === 0 ? 0 : Math.floor(Math.random() * 100) + 1,
    followersCount: Math.floor(Math.random() * 500),
    followingCount: i % 3 === 0 ? Math.floor(Math.random() * 5000) + 2000 : Math.floor(Math.random() * 400),
    hasProfilePic: i % 6 !== 0,
    isPrivate: Math.random() > 0.7
  }));
}

const sampleSize = Math.min(followers.length, 50);
const sample = followers.slice(0, sampleSize);

let suspiciousCount = 0;
const suspiciousReasons = {};

for (const follower of sample) {
  const issues = [];

  if (!follower.hasProfilePic) issues.push('NO_PROFILE_PIC');
  if ((follower.postsCount || 0) === 0) issues.push('ZERO_POSTS');

  const followingCount = follower.followingCount || 0;
  const followerCount = follower.followersCount || 0;
  if (followingCount > 2000 && followerCount < 100) issues.push('MASS_FOLLOWING_BOT');

  if (/[a-z]{3,}\d{5,}$/i.test(follower.username || '')) issues.push('NUMERIC_USERNAME');

  if (issues.length > 0) {
    suspiciousCount++;
    for (const issue of issues) {
      suspiciousReasons[issue] = (suspiciousReasons[issue] || 0) + 1;
    }
  }
}

const suspiciousRate = sampleSize > 0 ? (suspiciousCount / sampleSize) * 100 : 0;
let followerQualityScore = 0;

if (suspiciousRate > 60) followerQualityScore = 85;
else if (suspiciousRate > 40) followerQualityScore = 65;
else if (suspiciousRate > 20) followerQualityScore = 40;
else followerQualityScore = 10;

return [{
  json: {
    branch: 'follower_quality',
    sampleSize,
    suspiciousFollowers: suspiciousCount,
    suspiciousRate: suspiciousRate.toFixed(1),
    suspiciousReasonBreakdown: suspiciousReasons,
    followerQualityScore,
    verdict: followerQualityScore >= 70 ? 'HIGH_RISK' : followerQualityScore >= 40 ? 'MEDIUM_RISK' : 'LOW_RISK'
  }
}];

// MERGE ALL 5 BRANCH SCORES INTO WEIGHTED FRAUD SCORE

// Pull each branch result from workflow context
// In real execution these come via merge node inputs
const allItems = $input.all();

let spikeScore = 0, engagementScore = 0, commentRuleScore = 0;
let commentClaudeScore = 0, geoScore = 0, followerQualityScore = 0;
let spikeData = {}, engagementData = {}, commentData = {}, geoData = {}, followerData = {};
let claudeCommentAnalysis = {};

for (const item of allItems) {
  const d = item.json;
  switch (d.branch) {
    case 'follower_spike':
      spikeScore = d.spikeScore || 0;
      spikeData = d;
      break;
    case 'engagement_rate':
      engagementScore = d.engagementScore || 0;
      engagementData = d;
      break;
    case 'comment_prefilter':
      commentRuleScore = d.preFilterBotRate || 0;
      commentData = d;
      break;
    case 'comment_claude':
      commentClaudeScore = d.subtleBotScore || 0;
      claudeCommentAnalysis = d;
      break;
    case 'geo_mismatch':
      geoScore = d.geoMismatchScore || 0;
      geoData = d;
      break;
    case 'follower_quality':
      followerQualityScore = d.followerQualityScore || 0;
      followerData = d;
      break;
  }
}

// Combined comment score: 60% rules + 40% Claude intelligence
const combinedCommentScore = (commentRuleScore * 0.6) + (commentClaudeScore * 0.4);

// Weighted final fraud score
// Weights: Spike 25%, Engagement 20%, Comment 30%, Geo 15%, Quality 10%
const fraudScore = Math.min(100, Math.round(
  (spikeScore * 0.25) +
  (engagementScore * 0.20) +
  (combinedCommentScore * 0.30) +
  (geoScore * 0.15) +
  (followerQualityScore * 0.10)
));

const handle = $('Validate & Normalize Input').item.json.handle;
const platform = $('Validate & Normalize Input').item.json.platform;
const auditId = $('Validate & Normalize Input').item.json.auditId;

let overallVerdict, verdictColor, recommendation;
if (fraudScore >= 70) {
  overallVerdict = 'HIGH FRAUD RISK';
  verdictColor = 'RED';
  recommendation = 'DO NOT PROCEED. Strong indicators of purchased followers and/or inauthentic engagement. Request third-party verification before any partnership.';
} else if (fraudScore >= 45) {
  overallVerdict = 'MEDIUM FRAUD RISK';
  verdictColor = 'ORANGE';
  recommendation = 'PROCEED WITH CAUTION. Some anomalies detected. Negotiate lower rates, request audience insight screenshots directly from platform, and monitor campaign performance closely.';
} else {
  overallVerdict = 'LOW FRAUD RISK';
  verdictColor = 'GREEN';
  recommendation = 'SAFE TO PROCEED. Profile shows healthy organic indicators. Standard due diligence applies.';
}

return [{
  json: {
    auditId,
    handle,
    platform,
    fraudScore,
    overallVerdict,
    verdictColor,
    recommendation,
    scoreBreakdown: {
      followerSpikeScore: spikeScore,
      engagementAnomalyScore: engagementScore,
      commentBotScore: Math.round(combinedCommentScore),
      geoMismatchScore: geoScore,
      followerQualityScore
    },
    detailedFindings: {
      followerSpike: spikeData,
      engagement: engagementData,
      commentPrefilter: commentData,
      commentClaude: claudeCommentAnalysis,
      geographyMismatch: geoData,
      followerQuality: followerData
    },
    auditCompletedAt: new Date().toISOString()
  }
}];

