// BUILD FINAL STRUCTURED OUTPUT PAYLOAD

const scoreData = $('Scoring Engine – Weighted Fraud Score').item.json;
const reportText = $input.first().json.text || $input.first().json.content || 'Report generation pending.';

const fraudScore = scoreData.fraudScore;
const verdict = scoreData.overallVerdict;
const color = scoreData.verdictColor;

// Emoji indicator
const indicator = color === 'RED' ? '🚨' : color === 'ORANGE' ? '⚠️' : '✅';

const htmlReport = `
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Influencer Fraud Audit – @${scoreData.handle}</title>
<style>
  body { font-family: 'Segoe UI', Arial, sans-serif; max-width: 800px; margin: 40px auto; padding: 20px; color: #1a1a1a; }
  .header { background: #0f172a; color: white; padding: 32px; border-radius: 12px; margin-bottom: 24px; }
  .header h1 { margin: 0 0 8px 0; font-size: 24px; }
  .header p { margin: 0; opacity: 0.7; font-size: 14px; }
  .score-badge { display: inline-block; font-size: 52px; font-weight: 900; color: ${ color === 'RED' ? '#ef4444' : color === 'ORANGE' ? '#f97316' : '#22c55e'}; }
  .verdict { font-size: 18px; font-weight: 700; color: ${ color === 'RED' ? '#ef4444' : color === 'ORANGE' ? '#f97316' : '#22c55e'}; margin-top: 8px; }
  .breakdown { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 24px 0; }
  .signal-card { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 16px; }
  .signal-card h4 { margin: 0 0 4px 0; font-size: 13px; color: #64748b; text-transform: uppercase; letter-spacing: 0.5px; }
  .signal-card .signal-score { font-size: 28px; font-weight: 800; }
  .report-body { background: #f8fafc; border-radius: 8px; padding: 24px; line-height: 1.8; white-space: pre-wrap; font-size: 14px; }
  .rec-box { background: ${ color === 'RED' ? '#fef2f2' : color === 'ORANGE' ? '#fff7ed' : '#f0fdf4'}; border-left: 4px solid ${ color === 'RED' ? '#ef4444' : color === 'ORANGE' ? '#f97316' : '#22c55e'}; padding: 16px 20px; border-radius: 0 8px 8px 0; margin: 20px 0; }
  .meta { font-size: 12px; color: #94a3b8; margin-top: 32px; border-top: 1px solid #e2e8f0; padding-top: 16px; }
</style>
</head>
<body>
<div class="header">
  <h1>${indicator} Influencer Fraud Audit Report</h1>
  <p>@${scoreData.handle} &nbsp;|&nbsp; ${scoreData.platform.toUpperCase()} &nbsp;|&nbsp; Audit ID: ${scoreData.auditId}</p>
</div>

<div class="score-badge">${fraudScore}/100</div>
<div class="verdict">${indicator} ${verdict}</div>

<div class="breakdown">
  <div class="signal-card">
    <h4>Follower Spike</h4>
    <div class="signal-score" style="color:${scoreData.scoreBreakdown.followerSpikeScore >= 70 ? '#ef4444' : scoreData.scoreBreakdown.followerSpikeScore >= 40 ? '#f97316' : '#22c55e'}">${scoreData.scoreBreakdown.followerSpikeScore}</div>
    <small>Weight: 25%</small>
  </div>
  <div class="signal-card">
    <h4>Engagement Anomaly</h4>
    <div class="signal-score" style="color:${scoreData.scoreBreakdown.engagementAnomalyScore >= 70 ? '#ef4444' : scoreData.scoreBreakdown.engagementAnomalyScore >= 40 ? '#f97316' : '#22c55e'}">${scoreData.scoreBreakdown.engagementAnomalyScore}</div>
    <small>Weight: 20%</small>
  </div>
  <div class="signal-card">
    <h4>Comment Bot Score</h4>
    <div class="signal-score" style="color:${scoreData.scoreBreakdown.commentBotScore >= 70 ? '#ef4444' : scoreData.scoreBreakdown.commentBotScore >= 40 ? '#f97316' : '#22c55e'}">${scoreData.scoreBreakdown.commentBotScore}</div>
    <small>Weight: 30%</small>
  </div>
  <div class="signal-card">
    <h4>Geography Mismatch</h4>
    <div class="signal-score" style="color:${scoreData.scoreBreakdown.geoMismatchScore >= 70 ? '#ef4444' : scoreData.scoreBreakdown.geoMismatchScore >= 40 ? '#f97316' : '#22c55e'}">${scoreData.scoreBreakdown.geoMismatchScore}</div>
    <small>Weight: 15%</small>
  </div>
  <div class="signal-card">
    <h4>Follower Quality</h4>
    <div class="signal-score" style="color:${scoreData.scoreBreakdown.followerQualityScore >= 70 ? '#ef4444' : scoreData.scoreBreakdown.followerQualityScore >= 40 ? '#f97316' : '#22c55e'}">${scoreData.scoreBreakdown.followerQualityScore}</div>
    <small>Weight: 10%</small>
  </div>
</div>

<div class="rec-box"><strong>Recommendation:</strong> ${scoreData.recommendation}</div>

<div class="report-body">${reportText}</div>

<div class="meta">
  Generated by Influencer Fraud Detector &nbsp;|&nbsp; Powered by N8N + Claude AI &nbsp;|&nbsp; ${scoreData.auditCompletedAt}
</div>
</body>
</html>
`;

return [{
  json: {
    auditId: scoreData.auditId,
    handle: scoreData.handle,
    platform: scoreData.platform,
    fraudScore,
    verdict,
    recommendation: scoreData.recommendation,
    htmlReport,
    reportText,
    scoreBreakdown: scoreData.scoreBreakdown,
    auditCompletedAt: scoreData.auditCompletedAt
  }
}];

// Parse Claude comment analysis response and normalize branch tag
